import test from 'node:test';import assert from 'node:assert/strict';import {createRequestContext,authorizeTenantSelection,withTenantTransaction} from '../src/tenancy/context.mjs';import {tenantNamespace,assertTenantNamespace} from '../src/tenancy/namespaces.mjs';import {signEnvelope,verifyEnvelope} from '../src/tenancy/worker-envelope.mjs';import {createEvidenceKey,validateEvidenceKey} from '../src/evidence/object-keys.mjs';
const A='11111111-1111-4111-8111-111111111111',B='22222222-2222-4222-8222-222222222222',P='aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa';
test('request context is validated, normalized and frozen',()=>{const c=createRequestContext({tenantId:A.toUpperCase(),principalId:P,requestId:'req-1',correlationId:'cor-1',permissions:['b','a','a'],domains:['FINANCIAL'],maxSensitivity:2});assert.equal(c.tenantId,A);assert.deepEqual(c.permissions,['a','b']);assert(Object.isFrozen(c));assert.throws(()=>createRequestContext({...c,tenantId:'bad'}));});
test('tenant selector requires an active membership',()=>{assert.equal(authorizeTenantSelection({selectedTenantId:A,memberships:[{tenantId:A,active:true}]}),A);assert.throws(()=>authorizeTenantSelection({selectedTenantId:B,memberships:[{tenantId:A,active:true}]}),/Forbidden/);});
test('namespaces are tenant scoped and reject traversal or mismatch',()=>{const k=tenantNamespace('cache',A,'resource-list');assert.equal(assertTenantNamespace(k,'cache',A),k);assert.throws(()=>assertTenantNamespace(k,'cache',B));assert.throws(()=>tenantNamespace('cache',A,'../escape'));});
test('evidence keys cannot cross tenants',()=>{const k=createEvidenceKey(A,'aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa');assert.equal(validateEvidenceKey(k,A),k);assert.throws(()=>validateEvidenceKey(k,B));});
test('worker envelopes verify signature, expiry and tenant',()=>{const key=Buffer.alloc(32,7);const e=signEnvelope({tenantId:A,messageId:P,issuedAt:'2026-10-13T10:00:00Z',expiresAt:'2026-10-13T11:00:00Z',type:'evidence.scan',payloadHash:'a'.repeat(64)},key);assert.equal(verifyEnvelope(e,key,A,Date.parse('2026-10-13T10:30:00Z')).tenantId,A);assert.throws(()=>verifyEnvelope(e,key,B,Date.parse('2026-10-13T10:30:00Z')),/mismatch/);assert.throws(()=>verifyEnvelope(e,key,A,Date.parse('2026-10-13T12:00:00Z')),/expired/);});
test('transaction helper sets local context, commits, rolls back and releases',async()=>{const calls=[];const client={query:async(sql,args)=>{calls.push([sql,args]);if(sql==='WORKFAIL')throw new Error('x');return {rows:[]};},release:()=>calls.push(['RELEASE'])};const pool={connect:async()=>client};const c=createRequestContext({tenantId:A,principalId:P,requestId:'r',correlationId:'c'});await withTenantTransaction(pool,c,async db=>{await db.query('WORK');return 4;});assert.equal(calls[0][0],'BEGIN');assert.match(calls[1][0],/set_config/);assert.equal(calls.at(-2)[0],'COMMIT');assert.equal(calls.at(-1)[0],'RELEASE');calls.length=0;await assert.rejects(withTenantTransaction(pool,c,async db=>db.query('WORKFAIL')));assert.equal(calls.at(-2)[0],'ROLLBACK');assert.equal(calls.at(-1)[0],'RELEASE');});
